import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>بعض أجزاء الصورة لا يجب مشاركتها. وجه في الخلفية أو عنوان على رسالة أو كلمة مرور على شاشة قد يسبب ضررًا حقيقيًا إذا وصل إلى الأعين الخاطئة.</p>\n<p>التمويه والتبكسيل هما طريقتا إخفاء هذه التفاصيل. كلاهما يجعل المنطقة غير مقروءة، لكنهما يبدوان مختلفين ويحميان بشكل مختلف.</p>\n<p>يشرح هذا الدليل كلا الأسلوبين ومتى تستخدم كلًا منهما وكيف تطبقهما جيدًا. يغطي وضع الفرشاة ووضع الصورة الكاملة وإعدادات القوة والأخطاء التي تترك تفاصيل حساسة مقروءة.</p>\n<p>يمكنك تجربة كلا الأسلوبين مجانًا في المتصفح مع <a href=\"/ar/tammih-wa-tabaksul-as-sura/\">أداة تمويه وتبكسيل الصورة</a>، التي تتيح إخفاء المنطقة الحساسة فقط بالفرشاة أو الصورة كلها.</p>\n<h2 id=\"what-blur-does\">ماذا يفعل التمويه بالصورة</h2>\n<p>التمويه ينعّم المنطقة بمتوسط ألوان البكسلات المجاورة. الحواف الحادة تذوب والنص يصبح غير مقروء والوجوه تفقد ملامحها.</p>\n<p>التمويه الخفيف ينعّم التفاصيل قليلًا فقط، بينما التمويه القوي يحوّل المنطقة إلى غسل ناعم من اللون. وهو الأفضل للخلفيات ولإخفاء الهوية بنعومة. لكن لإخفاء معلومات حساسة يجب أن يكون التمويه قويًا.</p>\n<h2 id=\"what-pixelate-does\">ماذا يفعل التبكسيل بالصورة</h2>\n<p>التبكسيل يستبدل المنطقة بكتل كبيرة من اللون الواحد، مثل الفسيفساء. كل كتلة هي متوسط لون البكسلات تحتها، فتختفي كل التفاصيل الدقيقة.</p>\n<p>حجم الكتلة يتحكم في القوة. الكتل الصغيرة تحافظ على تلميح تقريبي للشكل، بينما الكتل الكبيرة تختزل المنطقة إلى بضعة مربعات مسطحة. والتبكسيل يبدو رقابة متعمدة، وهذا مفيد عندما تريد أن يعرف المشاهد أن شيئًا أُخفي.</p>\n<h2 id=\"why-censor-images\">لماذا يموّه الناس الصور ويبكسلونها</h2>\n<p>الخصوصية هي السبب الرئيسي. الصورة المشتركة على الإنترنت قد تكشف وجوهًا وعناوين ولوحات سيارات ومستندات، ورقابة هذه التفاصيل تحمي الأشخاص في الصورة.</p>\n<p>الآباء يموّهون وجوه أطفالهم قبل نشر صور عائلية علنًا، والصحفيون والباحثون يبكسلون الوجوه في القصص الحساسة، والشركات تموّه الشاشات في لقطاتها لأن لوحة تحكم قد تكشف أسماء عملاء أو روابط داخلية أو كلمات مرور.</p>\n<h2 id=\"brush-area-mode\">وضع منطقة الفرشاة: الرسم فوق التفاصيل</h2>\n<p>وضع منطقة الفرشاة يتيح رسم التمويه أو التبكسيل حيث تحتاجه تمامًا. اسحب الفرشاة فوق وجه أو لوحة أو سطر نص، ولا تُرقَّب إلا تلك الضربات.</p>\n<p>بقية الصورة تبقى حادة. هذه الدقة هي ما يجعل وضع الفرشاة الخيار الصحيح لمعظم أعمال الخصوصية، حيث يحتاج جزء صغير فقط من الصورة إلى الإخفاء. وحجم الفرشاة مهم: فرشاة كبيرة تغطي وجهًا بضربات قليلة، وفرشاة صغيرة تتبع كلمة واحدة.</p>\n<h2 id=\"whole-image-mode\">وضع الصورة الكاملة: تمويه كل شيء</h2>\n<p>وضع الصورة الكاملة يطبق التأثير على الصورة كلها دفعة واحدة. إنه الخيار الصحيح عندما تكون الصورة كلها حساسة، أو عندما تريد خلفية مموّهة لتصميم.</p>\n<p>الصورة المموّهة تمامًا خلفية جيدة للنص أو شريحة عرض تقديمي. الألوان والأجواء تبقى، لكن لا شيء يشتت عن الكلمات أعلاه. واستخدم هذا الوضع بحذر للخصوصية، لأنه يخفي الموضوع أيضًا.</p>\n<h2 id=\"smooth-blur-strength\">قوة التمويه الناعم: ما القوة الكافية؟</h2>\n<p>قوة التمويه مقياس، والقيمة الصحيحة تعتمد على ما تخفيه. الخلفية تحتاج تمويهًا خفيفًا فقط، بينما الوجه أو العنوان يحتاج تمويهًا قويًا.</p>\n<p>للوجوه، استخدم تمويهًا قويًا يزيل كل الملامح المعروفة. التمويه الخفيف الذي يترك العينين والابتسامة ظاهرين لا يحمي أحدًا. وللنص أيضًا يلزم تمويه قوي، لأن الكلمة المموّهة قليلًا يمكن تخمينها أحيانًا من طولها وشكلها.</p>\n<h2 id=\"mosaic-block-size\">حجم كتلة الفسيفساء: كتل أكبر تعني رقابة أكثر أمانًا</h2>\n<p>حجم كتلة الفسيفساء يعمل مثل قوة التمويه: الكتل الأكبر تخفي أكثر. حجم الكتلة الصغير يحافظ على تلميح تقريبي للشكل، بينما الحجم الكبير يختزل المنطقة إلى مربعات مسطحة.</p>\n<p>لقطات الشاشة الصغيرة يكفيها حجم كتلة معتدل، لأن النص صغير فحتى كتلة متواضعة تدمر أشكال الحروف تمامًا. أما الصور الكبيرة فاستخدم كتلًا أكبر، لأن الوجه في صورة عالية الدقة يحتاج كتلًا كبيرة لإخفاء الملامح.</p>\n<h2 id=\"brush-size-settings\">حجم الفرشاة: مطابقة الأداة مع التفاصيل</h2>\n<p>حجم الفرشاة يجب أن يطابق التفاصيل التي تخفيها. الوجه يحتاج فرشاة كبيرة، واللوحة تحتاج فرشاة متوسطة، والكلمة الواحدة تحتاج فرشاة صغيرة.</p>\n<p>الفرشاة الكبيرة جدًا ترقّب أكثر مما أردت، وقد تغطي وجهًا مجاورًا أو جزءًا مفيدًا من الصورة. والفرشاة الصغيرة جدًا تأخذ ضربات كثيرة لتغطية منطقة كبيرة، وقد تترك فجوات بين الضربات تكشف أجزاء من التفاصيل الحساسة.</p>\n<h2 id=\"hiding-faces\">كيف تخفي الوجوه كما ينبغي</h2>\n<p>الوجه يحتاج تغطية كاملة ليُخفى. العينان والأنف والفم وخط الشعر تحمل معلومات تعريفية، لذا يجب أن تغطي المنطقة الخاضعة للرقابة الرأس كاملًا.</p>\n<p>التبكسيل غالبًا هو الخيار الآمن للوجوه. الفسيفساء ذات الكتل الكبيرة تدمر الملامح تمامًا، بينما التمويه الخفيف قد يترك ما يكفي للتعرف. وغطِّ الرأس كله لا العينين فقط، فالشريط الأسود فوق العينين كليشيه سينمائي لا حماية حقيقية.</p>\n<h2 id=\"hiding-text-and-numbers\">كيف تخفي النصوص والأرقام والعناوين</h2>\n<p>النص أصعب في الإخفاء من الوجوه، لأن حرفًا واحدًا جزئيًا قد يكشف الكلمة. اللوحة أو العنوان أو كلمة المرور تحتاج تغطية كاملة.</p>\n<p>التبكسيل ذو الكتل الكبيرة هو الأسلوب الآمن للنص. يدمر أشكال الحروف تمامًا، بينما التمويه الناعم قد يترك مخطط الكلمات مقروءًا. وغطِّ السطر كله لا الكلمة الحساسة فقط، لأن طول السطر والكلمات المحيطة قد يكشفان الجزء المخفي.</p>\n<h2 id=\"hiding-backgrounds\">كيف تموّه الخلفيات للتركيز والخصوصية</h2>\n<p>الخلفية المموّهة تجعل الموضوع يبرز. مصورو البورتريه يستخدمون هذا التأثير منذ عقود، والتمويه الرقمي يعطي النتيجة نفسها بعد التصوير.</p>\n<p>ارسم التمويه فوق الخلفية بالفرشاة مع إبقاء الموضوع حادًا. وللخصوصية، قد تخفي الخلفية المموّهة موقعًا: لافتة شارع أو رقم منزل أو مبنى معروف في الخلفية قد يكشف أين التُقطت الصورة. واستخدم تمويهًا خفيفًا للخلفيات وقويًا للتفاصيل الحساسة.</p>\n<h2 id=\"formats-and-transparency\">الصيغ والشفافية</h2>\n<p>تقبل الأداة صيغ الصور الشائعة، بما فيها JPG وPNG وWebP وHEIC، بملفات حتى 20 ميغابايت. ويمكنك التصدير بصيغة JPG أو PNG أو WebP حسب حاجتك.</p>\n<p>التصدير بصيغة PNG أو WebP يحافظ على الشفافية في الصورة الأساسية. أما للصور الفوتوغرافية، فـJPG غالبًا هو أفضل تصدير، لأنه يبقي الملفات صغيرة ويعمل في كل مكان، والمناطق الخاضعة للرقابة تُضغط جيدًا.</p>\n<h2 id=\"privacy-local-processing\">الخصوصية: الرقابة دون رفع</h2>\n<p>كل التمويه والتبكسيل يحدث في متصفحك. صورك لا تُرفع أبدًا إلى خادم، وهذا مهم عندما تحتوي الصور على وجوه أو هويات أو عناوين خاصة.</p>\n<p>هذه أهم ميزة في أداة رقابة. الصورة التي تحتاج إلى إخفاء يجب ألا تُرسل أبدًا إلى خادم لا تراه، فقط لتمويه وجه. كما تزيل الأداة بيانات GPS من EXIF عند التصدير، وهي طبقة حماية ثانية.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة عند رقابة الصور</h2>\n<p>الخطأ الأكثر شيوعًا هو الرقابة الخفيفة جدًا. التمويه الناعم فوق وجه أو الفسيفساء الصغيرة فوق نص قد يتركان التفاصيل مقروءة، ما يبطل الغرض كله.</p>\n<p>من الأخطاء الأخرى إغفال انعكاس: قد يظهر وجه في مرآة أو نافذة أو نظارة شمسية في الصورة نفسها، وكل نسخة تحتاج رقابة. والناس ينسون أيضًا البيانات الوصفية، فقد تحمل الصورة إحداثيات GPS تكشف مكان التقاطها. وأخيرًا، لا تشارك الأصل بالخطأ.</p>\n<h2 id=\"censoring-workflow\">سير عمل للمشاركة الآمنة</h2>\n<p>افتح الصورة الأصلية واسرد كل ما يحتاج إلى إخفاء: الوجوه والعناوين واللوحات والشاشات والمستندات. راجع الخلفية إضافة إلى المقدمة.</p>\n<p>ارسم فوق كل عنصر بالفرشاة، مستخدمًا التبكسيل للنص وتمويهًا قويًا أو فسيفساء للوجوه. وقرّب بعد كل ضربة لتأكيد التغطية الكاملة. ثم صدّر النسخة الخاضعة للرقابة وراجعها بالحجم الكامل، وشارك الملف الخاضع للرقابة فقط.</p>\n<h2 id=\"blurring-for-video-thumbnails\">التمويه للصور المصغرة وأغلفة الفيديو</h2>\n<p>الصورة المموّهة خلفية جيدة للصورة المصغرة للفيديو. الألوان الناعمة تحدد الأجواء، بينما نص العنوان فوقها يبقى حادًا وسهل القراءة.</p>\n<p>استخدم وضع الصورة الكاملة مع تمويه معتدل للصور المصغرة. يجب أن تكون الصورة معروفة كمشهد لكن ناعمة بما يكفي ليهيمن النص على الإطار. وأبقِ الموضوع ظاهرًا قليلًا في التمويه، وصدّر الصور المصغرة كـJPG بجودة عالية.</p>\n<p>للخطوات التفصيلية، راجع <a href=\"/ar/blog/kayfiyya-tammih-wa-tabaksul-as-sura/\">كيف تموّه أو تبكسل صورة</a>. وللمقارنة، اقرأ <a href=\"/ar/blog/tammih-vs-tabaksul-as-sura/\">التمويه أم التبكسيل: كيف تخفي الوجوه والنصوص والتفاصيل</a>، ولإزالة بيانات الموقع تمامًا جرّب <a href=\"/ar/izala-bayanat-as-sura/\">أداة إزالة بيانات الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكن إزالة التمويه عن وجه لاحقًا؟","answer":"لا من الملف المنزّل إذا كان التمويه قويًا بما يكفي. التمويه يمتص البكسلات ويدمر التفاصيل الأصلية، فلا يبقى شيء لاستعادته. التمويه الخفيف جدًا يمكن إعادة تركيزه أحيانًا، فاستخدم قوة كافية."},{"question":"هل التبكسيل أكثر أمانًا من التمويه لإخفاء لوحة؟","answer":"نعم غالبًا، فالفسيفساء ذات الكتل الكبيرة تدمر أشكال الحروف والأرقام تمامًا، بينما التمويه الناعم قد يترك مخططاتها مقروءة. استخدم التبكسيل للنص والأرقام، والتمويه القوي أو الفسيفساء للوجوه."},{"question":"كيف أموّه وجهًا في صورة على هاتفي؟","answer":"افتح أداة تمويه وتبكسيل الصورة في متصفح هاتفك وارفع الصورة واختر وضع منطقة الفرشاة. ارسم فوق الوجه بإصبعك باستخدام فرشاة كبيرة وتمويه قوي أو فسيفساء، ثم نزّل النسخة الخاضعة للرقابة."},{"question":"هل يجب أن أموّه خلفية البورتريه كاملة؟","answer":"فقط إذا كشفت الخلفية شيئًا خاصًا مثل لافتة شارع أو رقم منزل. التمويه الخفيف يجعل الموضوع يبرز أيضًا، وهو اختيار إبداعي. استخدم تمويهًا قويًا للخصوصية وخفيفًا للتأثير الإبداعي."},{"question":"ماذا أفعل إذا فاتني موضع أثناء الرسم؟","answer":"استخدم زر التراجع لإزالة آخر ضربة، أو بدّل إلى فرشاة أصغر وارسم فوق المنطقة الفائتة. وقرّب بعد كل ضربة للتحقق من الفجوات. زر إعادة التعيين يمسح كل الضربات لتبدأ من جديد."},{"question":"هل تمويه الصورة يزيل بيانات موقعها؟","answer":"نعم، التصدير من الأداة يزيل وسوم GPS من EXIF في الملف. التمويه يخفي التفاصيل المرئية والتصدير يزيل سجل الموقع المخفي. احتفظ بالملف الأصلي إذا أردت الحفاظ على هذه البيانات."}];
